import React, { useContext, useEffect } from 'react';
import { graphql, navigate } from 'gatsby';
import styled from '@emotion/styled';
import { Box, Button, Typography } from '@mui/material';
import SingleProjectDetail from '../components/Project/SingleProjectDetail';
import ProjectMetadata from '../components/Project/ProjectMetadata';
import Navbar from '../components/Shared/Navbar';
import Layout from 'layouts';
import Footer from '../components/Codes/Footer';
import { TheAppContext } from '../provider/AppContext';
import FooterItems from '../components/Codes/Footer/FooterItems';
import useScrollToTop from '../hooks/useScrollToTop';
import { ChevronLeft, Close } from '@mui/icons-material';
const Styled__Wrap = styled(Box)`
  margin: auto;
  display: grid;
  grid-template-columns: auto 350px;
  color: white;
  max-width: 1200px;
  background-color: ${({ theme }) => theme.palette.background.default};
  ${({ theme }) => theme.breakpoints.down('md')} {
    grid-template-columns: auto;
    && .project-details {
      display: none;
    }
  }
`;
const SingleProject = ({ data }) => {
  useScrollToTop();
  const { project } = data;

  return (
    <>
      <Layout>
        <Box sx={{ backgroundColor: 'background.default' }}>
          <Navbar />
          <Styled__Wrap>
            <Box sx={{ py: 4, mx: 'auto', maxWidth: '400px' }}>
              <Button
                sx={{ mb: 3, cursor: 'pointer', pl: 3, pr: 4 }}
                onClick={() => navigate('/codes')}
                variant="outlined"
                startIcon={<ChevronLeft />}
              >
                Back
              </Button>

              <SingleProjectDetail project={project} />

              <Box>
                <Button
                  variant="outlined"
                  fullWidth
                  sx={{ mt: 3, mb: 20 }}
                  onClick={() => navigate('/codes#projects')}
                >
                  Back To All
                </Button>
              </Box>
            </Box>
            <Box className="project-details">
              <ProjectMetadata project={project} />
            </Box>
          </Styled__Wrap>
        </Box>

        <Box sx={{ marginTop: '1vh' }}>
          <Footer />
        </Box>
      </Layout>
    </>
  );
};

export default SingleProject;
export const pageQuery = graphql`
  query MyQuery($id: String!) {
    project: strapiProject(id: { eq: $id }) {
      Completed(fromNow: true)
      dateCompleted: Completed
      Title
      RepoLink
      LiveLink
      skills {
        skill {
          Link
          Mastery
          SkillName
        }
        SkillCategory
      }
      Narrative {
        data {
          childMarkdownRemark {
            html
          }
        }
      }
      tags {
        tagName
      }
      Cover {
        alternativeText
        localFile {
          url
          childImageSharp {
            gatsbyImageData(layout: FULL_WIDTH)
            fixed {
              ...GatsbyImageSharpFixed
            }
          }
        }
      }
      Gallery {
        localFile {
          childImageSharp {
            gatsbyImageData(layout: FULL_WIDTH)
            fixed {
              ...GatsbyImageSharpFixed
            }
          }
        }
      }
    }
  }
`;

